@@ -0,0 +1,133 @@
+package server
+
+import (
+	"crypto/rand"
+	"encoding/json"
+	"math/big"
+	"net/http"
+	"regexp"
+	"strings"
+
+	"git.aisoftwarefactory.world/linkshort4/linkshort4/internal/session"
+)
+
+var slugRegex = regexp.MustCompile(`^[a-z0-9-]{3,32}$`)
+
+const slugChars = "abcdefghijklmnopqrstuvwxyz0123456789-"
+
+func generateSlug() string {
+	b := make([]byte, 7)
+	for i := range b {
+		n, _ := rand.Int(rand.Reader, big.NewInt(int64(len(slugChars))))
+		b[i] = slugChars[n.Int64()]
+	}
+	return string(b)
+}
+
+func handleCreateLink(w http.ResponseWriter, r *http.Request) {
+	userID, ok := session.UserID(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	var req struct {
+		URL  string `json:"url"`
+		Slug string `json:"slug"`
+	}
+	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request"})
+		return
+	}
+	req.URL = strings.TrimSpace(req.URL)
+	if len(req.URL) == 0 || len(req.URL) > 2048 {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid url"})
+		return
+	}
+	if !strings.HasPrefix(req.URL, "http://") && !strings.HasPrefix(req.URL, "https://") {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid url scheme"})
+		return
+	}
+	slug := req.Slug
+	if slug != "" {
+		if !slugRegex.MatchString(slug) {
+			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid slug"})
+			return
+		}
+	} else {
+		slug = generateSlug()
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	link, err := s.CreateLink(r.Context(), userID, slug, req.URL)
+	if err != nil {
+		writeJSON(w, http.StatusConflict, map[string]string{"error": "slug already taken"})
+		return
+	}
+	writeJSON(w, http.StatusCreated, map[string]string{"slug": link.Slug, "url": link.URL})
+}
+
+func handleListLinks(w http.ResponseWriter, r *http.Request) {
+	userID, ok := session.UserID(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	links, err := s.ListLinksByUser(r.Context(), userID)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	type linkResp struct {
+		Slug   string `json:"slug"`
+		URL    string `json:"url"`
+		Clicks int64  `json:"clicks"`
+	}
+	var resp []linkResp
+	for _, l := range links {
+		stats, err := s.GetClickStats(r.Context(), l.ID)
+		if err != nil {
+			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+			return
+		}
+		var total int64
+		for _, cs := range stats {
+			total += cs.Count
+		}
+		resp = append(resp, linkResp{Slug: l.Slug, URL: l.URL, Clicks: total})
+	}
+	if resp == nil {
+		resp = []linkResp{}
+	}
+	writeJSON(w, http.StatusOK, resp)
+}
+
+func handleDeleteLink(w http.ResponseWriter, r *http.Request) {
+	userID, ok := session.UserID(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	slug := strings.TrimPrefix(r.URL.Path, "/api/links/")
+	if slug == "" {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "missing slug"})
+		return
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	if err := s.DeleteLink(r.Context(), slug, userID); err != nil {
+		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
+		return
+	}
+	w.WriteHeader(http.StatusNoContent)
+}
