+func TestCreateLink(t *testing.T) {
+	srv, _ := newTestServer(t)
+	client := &http.Client{}
+
+	body := bytes.NewReader([]byte(`{"email":"linktest@example.com","password":"1234567890"}`))
+	req, err := http.NewRequest("POST", srv.URL+"/api/signup", body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.Header.Set("Content-Type", "application/json")
+	res, err := client.Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusCreated {
+		t.Fatalf("signup: status %d, want 201", res.StatusCode)
+	}
+	cookies := res.Cookies()
+	var sessionCookie *http.Cookie
+	for _, c := range cookies {
+		if c.Name == "session" {
+			sessionCookie = c
+			break
+		}
+	}
+	if sessionCookie == nil {
+		t.Fatal("signup did not set session cookie")
+	}
+
+	linkBody := bytes.NewReader([]byte(`{"url":"https://example.com/long-url"}`))
+	linkReq, err := http.NewRequest("POST", srv.URL+"/api/links", linkBody)
+	if err != nil {
+		t.Fatal(err)
+	}
+	linkReq.Header.Set("Content-Type", "application/json")
+	linkReq.AddCookie(sessionCookie)
+	linkRes, err := client.Do(linkReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	linkB, _ := io.ReadAll(linkRes.Body)
+	_ = linkRes.Body.Close()
+	if linkRes.StatusCode != http.StatusCreated {
+		t.Fatalf("POST /api/links: status %d, want 201; body: %s", linkRes.StatusCode, linkB)
+	}
+	var linkResp map[string]string
+	if err := json.Unmarshal(linkB, &linkResp); err != nil {
+		t.Fatalf("unmarshal link response: %v", err)
+	}
+	if linkResp["slug"] == "" {
+		t.Error("POST /api/links: slug is empty")
+	}
+	if linkResp["url"] != "https://example.com/long-url" {
+		t.Errorf("POST /api/links: url = %q, want https://example.com/long-url", linkResp["url"])
+	}
+}
